import{_ as t,o as a,c as l,a5 as r}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"七、在网关中加入熔断器Hystrix","description":"","frontmatter":{"title":"七、在网关中加入熔断器Hystrix","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/七、在网关中加入熔断器Hystrix.md","filePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/七、在网关中加入熔断器Hystrix.md"}'),i={name:"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/七、在网关中加入熔断器Hystrix.md"};function o(n,e,p,d,c,s){return a(),l("div",null,[...e[0]||(e[0]=[r(`<div><p>在微服务中，各个系统之间相互调用，难免出现某个服务挂掉的情况，此时熔断器机制就很重要，我们可以利用熔断器，将超时的请求予以异常处理，避免形成死循环的调用链。</p><p>由于我们刚才在搭建网关时没用选择熔断器依赖，所以在网关项目的<code>pom.xml</code>手动添加以下依赖：</p><p>&lt;dependency&gt; &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt; &lt;artifactId&gt;spring-cloud-starter-netflix-hystrix&lt;/artifactId&gt; &lt;/dependency&gt; 如果报错：<code>Could not find artifact org.springframework.cloud:spring-cloud-starter-netflix-eureka-client:pom</code> 请加上版本信息即可； &lt;dependency&gt; &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt; &lt;artifactId&gt;spring-cloud-starter-netflix-hystrix&lt;/artifactId&gt; &lt;version&gt;2.2.5.RELEASE&lt;/version&gt; &lt;/dependency&gt;</p><p><em>如果报错：<em><em>SpringCloud</em> <em>集成</em> <em>Hystrix</em> <em>报错</em></em>: Unable to find GatewayFilterFactory with name Hystrix</em><em>解决：</em><em>这个包是使用的 Gateway 2.2.5 之后的版本（不包括2.2.5），这个版本里面是没有 Hystrix 这个过滤器的；换到 Gateway 2.2.5（包括2.2.5）以下的版本就有了；</em></p><p>然后修改配置文件：</p><ul><li>server:</li><li><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>网关端口</p><ul><li>8083</li><li>port: 8083</li><li>spring:</li><li>application:</li><li><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>在服务中心的应用名称</p><ul><li>name: gateway</li><li>cloud:</li><li>gateway:</li><li>discovery:</li><li>locator:</li><li><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>自动映射<code>eureka</code>下的服务路由</p><ul><li>enabled: true</li><li><h1 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>开启服务名称小写</p><ul><li>lower-case-service-id: true</li><li><h1 id="-4" tabindex="-1"><a class="header-anchor" href="#-4" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>服务熔断，降级</p><pre><code>  default-filters:
    - name: Hystrix
      args:
        name: fallbackcmd
        fallbackUri: forward:/fallback
</code></pre><p>eureka: client: service-url: defaultZone: <a href="http://localhost:8080/eureka/" target="_blank" rel="noreferrer">http://localhost:8080/eureka/</a></p><h1 id="hystrix" tabindex="-1">hystrix <a class="header-anchor" href="#hystrix" aria-label="Permalink to &quot;hystrix&quot;">​</a></h1><p>熔断器，<code>3</code>秒后自动超时</p><ul><li>hystrix:</li><li>command:</li><li>fallbackcmd:</li><li>execution:</li><li>isolation:</li><li>thread:</li><li>timeoutInMilliseconds: 3000</li></ul><p>上面配置里的<code>fallbackUri</code>，是指熔断时的回调地址，也就是说一旦服务响应超过了<code>3</code>秒，会转发到这个地址，执行自定义的业务操作，我们往往是返回一个错误码。注意，这个回调的<code>controller</code>，是要写到网关里的，所以我们在网关项目里新建如下：</p><p>package com.blog.wang.cloudgateway.controller;</p><p>import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController;</p><p>import java.util.HashMap; import java.util.Map;</p><p>@RestController public class ErrorController {</p><pre><code>/**
 *
</code></pre><p>服务响应超时的回调 <code>* @return</code> 错误码</p><pre><code> * */
@RequestMapping(value = &quot;/fallback&quot;)
public Object fallback () \\{
    Map\\&lt;String , Object\\&gt; result = new HashMap\\&lt;\\&gt;();
    result.put(&quot;code&quot; , 0);
    result.put(&quot;msg&quot; , &quot;
</code></pre><p>服务器繁忙</p><p>&quot;); result.put(&quot;state&quot; , false); return result; } }</p><p>然后我们在第一个服务节点里，添加如下代码，模拟超时：</p><p>再通过我们的网关访问<code>API</code>接口，发现每当请求到达第一个服务节点时，就会提示服务器繁忙：</p><p>小结 以上就是基本的<code>Spring Cloud</code>脚手架，相信还是可以满足大多数人的开发需求的。不足的地方有很多，比如处理跨域、线上环境的注册中心配置、<code>Gateway</code>网关的多种配置、熔断器的各种配置，以后都会慢慢地补上，还请大家海涵吧！</p><p>原文链接：<code>https://blog.csdn.net/wzy18210825916/article/details/103444346</code></p></div>`,1)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
